import React, { useMemo } from 'react';

import type { ChartOptions } from 'chart.js';
import { Bar, ComparisonLine, Line } from 'components';
import { theme } from 'theme';

import type { PerformanceAndBreakdownOvertimeData } from '../../types';
import {
  StyledBarChartColumn,
  StyledChartsGrid,
  StyledChartWrapper,
  StyledLineChartColumn,
} from './LineBarChartsGrid.styles';

interface LineBarChartsGridProps {
  data: PerformanceAndBreakdownOvertimeData;
  barOptions?: ChartOptions<'bar'>;
  dataTestId?: string;
}

export const LineBarChartsGrid: React.FC<LineBarChartsGridProps> = ({
  data,
  barOptions,
  dataTestId,
}) => {
  const resolvedBarOptions = useMemo((): ChartOptions<'bar'> => {
    const base: ChartOptions<'bar'> = barOptions ?? {
      layout: {
        padding: { top: 40, left: 16, right: 16 },
      },
      scales: {
        y: {
          min: data.barChart.suggestedMin ?? 0,
          max: data.barChart.suggestedMax ?? 25,
          ticks: { maxTicksLimit: 5 },
        },
      },
    };

    return {
      ...base,
      plugins: {
        ...base.plugins,
        legend: { display: false },
      },
    };
  }, [barOptions, data.barChart.suggestedMin, data.barChart.suggestedMax]);

  return (
    <StyledChartsGrid data-testid={dataTestId}>
      <StyledLineChartColumn>
        <StyledChartWrapper>
          <Line
            datasets={data.lineChart.datasets}
            labels={data.lineChart.labels}
            labelColors={[theme.colors.txt.secondary, theme.colors.txt.default]}
            options={{
              layout: { padding: { top: 20 } },
              plugins: {
                legend: { display: false },
              },
              scales: {
                y: {
                  min: data.lineChart.suggestedMin ?? 0,
                  max: data.lineChart.suggestedMax ?? 25,
                  beginAtZero: true,
                  ticks: {
                    stepSize: 5,
                    maxTicksLimit: 6,
                  },
                  afterFit: (axis) => {
                    axis.width = 45;
                  },
                },
              },
            }}
            showDivider
          />
        </StyledChartWrapper>
        {data.lineChart.comparisonLine && (
          <ComparisonLine
            data={data.lineChart.comparisonLine.data}
            gridColumnsLength={data.lineChart.labels.length}
            gridConfig={{ paddingLeft: 5, paddingRight: 0 }}
            borderConfig={{ marginLeft: 40, marginRight: 8 }}
          />
        )}
      </StyledLineChartColumn>
      <StyledBarChartColumn>
        <StyledChartWrapper>
          <Bar
            datasets={data.barChart.datasets}
            labels={data.barChart.labels}
            formattedData={data.barChart.formattedData}
            stripedIndexes={data.barChart.stripedIndexes ?? []}
            size="medium"
            showGrid={false}
            showDivider={false}
            axisType="none"
            options={resolvedBarOptions}
          />
        </StyledChartWrapper>
        {data.barChart.comparisonLine && (
          <ComparisonLine
            data={data.barChart.comparisonLine.data}
            gridColumnsLength={data.barChart.labels.length}
            gridConfig={{ paddingLeft: 0, paddingRight: 0 }}
            borderConfig={{ marginLeft: 16, marginRight: 16 }}
          />
        )}
      </StyledBarChartColumn>
    </StyledChartsGrid>
  );
};
